def fit_models():
    for c in checks:
        print('\n###', c)
        xs = [raw[c][s] for s in segments]
        meds = np.array([np.median(x) for x in xs])
        families = {
            'normal': (lambda z: stats.norm.logpdf(z), False),
            'logistic': (lambda z: stats.logistic.logpdf(z), False),
            'laplace': (lambda z: stats.laplace.logpdf(z), False),
            'cauchy': (lambda z: stats.cauchy.logpdf(z), False),
            't': (None, True),
        }
        for name, (logpdf, fit_df) in families.items():
            def objective(p):
                loc = p[:6]
                scale = np.exp(p[6])
                df = np.exp(p[7]) if fit_df else None
                val = 0.
                for j,x in enumerate(xs):
                    z = (x-loc[j])/scale
                    val -= np.sum((stats.t.logpdf(z,df) if fit_df else logpdf(z)) - np.log(scale))
                return val
            p0 = np.r_[meds, np.log(50), np.log(3)] if fit_df else np.r_[meds, np.log(50)]
            res = optimize.minimize(objective,p0,method='Nelder-Mead', options={'maxiter':30000,'xatol':1e-8,'fatol':1e-6})
            if fit_df:
                extras = f'df={np.exp(res.x[7]):.4g}'
            else:
                extras = ''
            print(name, 'nll',round(res.fun,3), 'loc',np.round(res.x[:6],2), 'scale',round(np.exp(res.x[6]),3),extras)

if __name__ == '__main__':
    for c in checks:
        print('\n',c)
        for s in segments:
            x=raw[c][s]
            print(s, 'median',np.median(x), 'mean',np.mean(x), 'q25/75',np.quantile(x,[.25,.75]), 'sd',np.std(x))
    fit_models()

